// Import necessary libraries and utility functions
import proj4 from "proj4";
import {
  parseStringArrays,
  coordinatesOutOfRange,
  reprojectCoordinates,
  addIdToGeoJson,
  collectDataDashboardProperties,
  determineType,
  generateDefaultColor,
  readFileAsText,
  reasonableRoundUp,
  reasonableRoundDown,
  calculatePropertySums
} from "./Utilities";

// Helper function to generate unique scenario names
const generateUniqueScenarioName = (name, scenarioNamesSet) => {
  let uniqueName = name;
  let counter = 1;
  while (scenarioNamesSet.has(uniqueName)) {
    uniqueName = `${name} (${counter})`;
    counter++;
  }
  scenarioNamesSet.add(uniqueName);
  return uniqueName;
};

// Helper function to determine the prefix based on the dashboard name
const determinePrefix = (dashboardName) => {
  if (dashboardName.includes("EnergyGrid")) return "G";
  if (dashboardName.includes("StreetMobility")) return "S";
  if (dashboardName.includes("EnergyBuilding") || dashboardName.includes("BuildingCO2"))
    return "B";
  return "D"; // Default to 'D' for DataDashboard or other unspecified types
};

// Helper function to update numeric properties map
const updateNumericProperties = (numericProperties, feature, dashboardNames, config) => {
  Object.keys(feature.properties || {}).forEach((prop) => {
    let value = feature.properties[prop];
    // Convert string numeric values to numbers
    if (typeof value === "string" && !isNaN(value)) {
      value = Number(value);
    }
    // Check if the value is numeric and update min/max accordingly
    if (value !== null && typeof value === "number") {
      if (!numericProperties.has(prop)) {
        numericProperties.set(prop, { min: value, max: value });
      } else {
        const current = numericProperties.get(prop);
        numericProperties.set(prop, {
          min: reasonableRoundUp(Math.min(current.min, value)),
          max: reasonableRoundDown(Math.max(current.max, value)),
        });
      }

      // Defensive check: Ensure config[dashboardName] and chartProperties exist
      dashboardNames.forEach((dashboardName) => {
        if (!config[dashboardName]) {
          config[dashboardName] = {}; // Initialize dashboard config if it doesn't exist
        }
        if (!config[dashboardName].chartProperties) {
          config[dashboardName].chartProperties = []; // Initialize chartProperties if it doesn't exist
        }
        // Add numeric property to the appropriate dashboard's chartProperties, avoiding duplicates
        if (!config[dashboardName].chartProperties.includes(prop)) {
          config[dashboardName].chartProperties.push(prop);
        }
      });
    }
  });
};

// Main function to handle file uploads and update the configuration
export const FileUploadLogic = async (files, config, setConfig, setFileProgress) => {
  // Initialize variables for dashboards, properties, and scenario names
  const dashboards = {};
  const numericProperties = new Map();
  const scenarioNamesSet = new Set();
  const defaultProperties = config.DataDashboard?.properties || [];
  const tiledDataFeatures = {};

  // Iterate through each file to process GeoJSON data
  for (const [index, file] of files.entries()) {
    // Read the file as text and parse as JSON, with coordinate transformation if necessary
    const json = await readFileAsText(file);

    let dashboardNames = [];
    let scenarioName = file.name;

    // Determine scenario name from the first feature's properties if available
    if (json.features && json.features.length > 0) {
      const firstFeature = json.features[0];

      if (firstFeature.properties && firstFeature.properties.name) {
        scenarioName = firstFeature.properties.name;
      }

      scenarioName = generateUniqueScenarioName(scenarioName, scenarioNamesSet);

      // Iterate through each feature in the GeoJSON data
      for (const [featureIndex, feature] of json.features.entries()) {
        // Update file progress based on the feature index
        setFileProgress((prevProgress) => ({
          ...prevProgress,
          [file.name]: ((featureIndex + 1) / json.features.length) * 100,
        }));

        // Collect dashboard names from feature properties if they exist
        if (feature.properties && feature.properties.type) {
          const names = feature.properties.type.split(",").map((name) => name.trim().toLowerCase()); // Convert to lowercase
          dashboardNames.push(...names);
        }

        // Collect numeric properties and their min/max values
        updateNumericProperties(numericProperties, feature, dashboardNames, config);
      }
    }

    // If no dashboard names are found, default to "DataDashboard"
    if (dashboardNames.length === 0) {
      dashboardNames = ["DataDashboard"];
    }

    dashboardNames.forEach((dashboardName) => {
      const lowerDashboardName = dashboardName.toLowerCase(); // Ensure lowercase comparison
    
      // Find matching dashboard config in a case-insensitive way
      const matchingDashboard = Object.keys(config).find(
        (configName) => configName.toLowerCase() === lowerDashboardName
      );
    
      if (matchingDashboard) {
        const prefix = determinePrefix(matchingDashboard);
        const jsonWithIDs = addIdToGeoJson(json, prefix);
    
        if (config[matchingDashboard]?.tiledData) {
          if (!tiledDataFeatures[matchingDashboard]) {
            tiledDataFeatures[matchingDashboard] = [];
          }
          tiledDataFeatures[matchingDashboard].push(...jsonWithIDs.features);
        } else {
          if (!dashboards[matchingDashboard]) {
            dashboards[matchingDashboard] = [];
          }
          dashboards[matchingDashboard].push({ name: scenarioName, data: jsonWithIDs });
        }
      }
    });
  }

  // Process tiled data after all files have been read
  Object.keys(tiledDataFeatures).forEach((dashboardName) => {
    const combinedFeatures = tiledDataFeatures[dashboardName];
    const combinedJson = {
      type: "FeatureCollection",
      features: combinedFeatures
    };
    const scenarioName = `${dashboardName}_Combined`;
    if (!dashboards[dashboardName]) {
      dashboards[dashboardName] = [];
    }
    dashboards[dashboardName].push({ name: scenarioName, data: combinedJson });
  });

  // **Only collect properties specific to DataDashboard**
  const dataDashboardProperties = collectDataDashboardProperties(
    dashboards["DataDashboard"] || []
  );

  // **Filter numeric properties based on the collected DataDashboard properties**
  const filteredNumericProperties = Array.from(numericProperties.keys()).filter(
    (prop) => dataDashboardProperties.includes(prop)
  );

  if (filteredNumericProperties.length > 0) {
    // **Map the filtered properties to the desired format for updating the config, including 'type'**
    const updatedProperties = filteredNumericProperties.map((prop, index) => {
      const defaultProp = defaultProperties.find((p) => p.name === prop);

      // **Determine the type by examining the first feature that has this property**
      let propType = "unknown";
      for (const file of dashboards["DataDashboard"] || []) {
        for (const feature of file.data.features) {
          if (feature.properties && feature.properties.hasOwnProperty(prop)) {
            propType = determineType(feature.properties[prop]);
            break;
          }
        }
        if (propType !== "unknown") break;
      }

      return {
        name: prop,
        type: propType, // **Include the type here**
        color: defaultProp?.color || generateDefaultColor(index),
        min: numericProperties.get(prop).min,
        max: numericProperties.get(prop).max,
        total: defaultProp?.total || 1000,
        colorScale: defaultProp?.colorScale || "Viridis",
      };
    });

    // **Update only the DataDashboard configuration with the new properties**
    setConfig((prevConfig) => ({
      ...prevConfig,
      DataDashboard: {
        ...prevConfig.DataDashboard,
        properties: updatedProperties,
        selectedProperty: updatedProperties[0].name,
        tooltipProperties: dataDashboardProperties,
      },
    }));
  }

  // **Ensure other dashboards remain unchanged**
  // No changes are made to other dashboards in the config

  // Update the config with the collected numeric chartProperties for each dashboard
  setConfig((prevConfig) => ({
    ...prevConfig,
    ...Object.keys(dashboards).reduce((accumulator, dashboardName) => {
      // Skip updating DataDashboard since it's already handled
      if (dashboardName === "DataDashboard") return accumulator;

      const newChartProperties = dashboards[dashboardName]
        .flatMap((file) => Object.keys(file.data.features[0]?.properties || {}))
        .filter(
          (prop) =>
            !isNaN(
              dashboards[dashboardName][0].data.features[0].properties[prop]
            ) &&
            !(prevConfig[dashboardName]?.chartProperties || []).includes(prop)
        ); // Ensure uniqueness and numeric filter

      // Merge new chart properties with existing config for each dashboard
      accumulator[dashboardName] = {
        ...prevConfig[dashboardName],
        chartProperties: [
          ...(prevConfig[dashboardName]?.chartProperties || []),
          ...newChartProperties,
        ],
      };

      //console.log(accumulator)

      return accumulator;
    }, {}),
  }));

  //console.log("Updated dashboards:", dashboards);

  // Return the updated dashboards object
  return dashboards;
};
