import React, { useRef, useEffect } from "react";
import * as d3 from "d3";
import chroma from "chroma-js";
import "../App.css";

const LegendHistogram = ({
  data,
  propertyConfig,
  colorScale,
  xAxisLabel,
  min,
  max,
  bincount,
  selectedIndex,
}) => {
  const histogramRef = useRef();

  const formatValue = (value) => {
    if (value >= 1e6) return `${(value / 1e6).toFixed(1)}M`;
    if (value >= 1e3) return `${(value / 1e3).toFixed(1)}k`;
    return value.toString();
  };

  useEffect(() => {
    if (!propertyConfig || !colorScale) return;

    const propertyType = propertyConfig.type;
    d3.select(histogramRef.current).selectAll("*").remove();

    let processedData = [];
    const lowerThreshold = min - 10;
    const upperThreshold = max + 10;

    if (isNaN(min) || isNaN(max)) {
      console.error("Invalid min or max values", min, max);
      return;
    }

    if (propertyType === "number") {
      processedData = data.filter(
        (d) => d !== null && !isNaN(d) && d >= lowerThreshold && d <= upperThreshold
      );
    } else if (propertyType === "array") {
      processedData = data
        .map((d) => (Array.isArray(d) ? d[selectedIndex] : null))
        .filter(
          (d) => d !== null && !isNaN(d) && d >= lowerThreshold && d <= upperThreshold
        );
    } else if (propertyType === "category") {
      processedData = data.filter((d) => d !== null && d !== undefined);
    } else {
      console.error("Unsupported property type:", propertyType);
      return;
    }

    const margin = { top: 20, right: 30, bottom: 60, left: 60 };
    const width = 350 - margin.left - margin.right;
    const height = 200 - margin.top - margin.bottom;

    const svg = d3
      .select(histogramRef.current)
      .append("svg")
      .attr("width", width + margin.left + margin.right)
      .attr("height", height + margin.top + margin.bottom)
      .append("g")
      .attr("transform", `translate(${margin.left},${margin.top})`);

    const chromaScale = chroma.scale(colorScale || ["#000", "#fff"]).mode("lab");

    if (propertyType === "number" || propertyType === "array") {
      const x = d3.scaleLinear().domain([min, max]).range([0, width]);
      const binGenerator = d3.bin().domain(x.domain()).thresholds(bincount);
      let bins = binGenerator(processedData);

      const yMax = d3.max(bins, (d) => d.length);
      const y = d3.scaleLinear().domain([0, yMax]).range([height, 0]);

      svg.append("g")
        .call(d3.axisLeft(y).ticks(Math.min(8, yMax)))
        .selectAll("text")
        .style("text-anchor", "end");

      svg.append("g")
        .attr("transform", `translate(0,${height})`)
        .call(d3.axisBottom(x))
        .selectAll("text")
        .attr("transform", "rotate(45)")
        .attr("x", 13)
        .attr("y", 15)
        .style("text-anchor", "start");

      const bars = svg
        .selectAll("rect")
        .data(bins)
        .enter()
        .append("rect")
        .attr("x", (d) => x(d.x0))
        .attr("y", (d) => {
          const barHeight = height - y(d.length);
          return barHeight < 3 ? y(3) : y(d.length);
        })
        .attr("width", (d) => x(d.x1) - x(d.x0) - 1)
        .attr("height", (d) => {
          const barHeight = height - y(d.length);
          return barHeight < 3 ? 3 : barHeight;
        })
        .attr("fill", (d) => chromaScale((d.x0 - min) / (max - min)).hex());

      // Add labels below each bar, with increased gap from the x-axis label
      svg
        .selectAll("text.bar-label")
        .data(bins)
        .enter()
        .append("text")
        .attr("class", "bar-label")
        .attr("x", (d) => x(d.x0) + (x(d.x1) - x(d.x0)) / 2)
        .attr("y", height +15) // Set a larger gap from x-axis label
        .attr("text-anchor", "middle")
        .attr("font-size", "9px")
        .attr("fill", "grey") // Set color to grey
        .text((d) => formatValue(d.length));

      svg
        .append("text")
        .attr("x", width / 2)
        .attr("y", height + margin.bottom -5)
        .attr("text-anchor", "middle")
        .attr("font-size", "12px")
        .text(xAxisLabel);

      svg
        .append("text")
        .attr("transform", "rotate(-90)")
        .attr("y", 0 - margin.left + 5)
        .attr("x", 0 - height / 2)
        .attr("dy", "1em")
        .attr("text-anchor", "middle")
        .attr("font-size", "12px")
        .text("Count");
    }
  }, [data, propertyConfig, colorScale, xAxisLabel, min, max, bincount, selectedIndex]);

  return <div ref={histogramRef} className="chart-area"></div>;
};

export default LegendHistogram;
